head.b:skin:
:root {
  --bg-void: #050811;
  --bg-surface: #0a0f1d;
  --bg-surface-elevated: #0f172a;
  --bg-glass-card: rgba(18, 27, 49, 0.7);

  --accent-emerald: #10b981;
  --accent-emerald-bright: #34d399;
  --accent-emerald-glow: rgba(16, 185, 129, 0.3);
  --accent-cyan: #06b6d4;
  --accent-gold: #f59e0b;
  --accent-red: #ef4444;

  --text-white: #f8fafc;
  --text-silver: #cbd5e1;
  --text-muted: #64748b;

  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-accent: rgba(16, 185, 129, 0.35);

  --font-display: 'Cairo', system-ui, -apple-system, sans-serif;
  --font-mono: 'Chakra Petch', 'JetBrains Mono', monospace;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}

body {
  background-color: var(--bg-void);
  background-image: 
    radial-gradient(circle at 50% 0%, rgba(16, 185, 129, 0.12) 0%, transparent 60%),
    radial-gradient(circle at 90% 40%, rgba(16, 185, 129, 0.06) 0%, transparent 45%);
  background-attachment: fixed;
  color: var(--text-white);
  font-family: var(--font-display);
  direction: rtl;
  text-align: right;
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
  padding-bottom: 90px;
}

.main-wrapper {
  max-width: 1100px;
  margin: 0 auto;
  padding: 16px 20px;
}

/* Top Brand Header matching Cloudflare React screenshot */
.header-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-subtle);
}
.brand-identity {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--text-white);
}
.brand-crest {
  width: 44px;
  height: 44px;
  background: linear-gradient(135deg, #10b981 0%, #06b6d4 100%);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 16px var(--accent-emerald-glow);
}
.brand-title-wrap h1 {
  font-size: 20px;
  font-weight: 900;
  letter-spacing: -0.5px;
  line-height: 1.2;
}
.brand-subtitle {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 700;
}
.header-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}
.tz-dropdown {
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid var(--border-subtle);
  color: var(--text-silver);
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 20px;
  outline: none;
  cursor: pointer;
}
.tz-dropdown:focus {
  border-color: var(--accent-emerald);
}
.theme-toggle-pill {
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid var(--border-subtle);
  color: var(--text-silver);
  font-size: 11px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 20px;
  cursor: pointer;
}

/* Sponsor Billboard Banner (Top Ad Slot) */
.sponsor-billboard-card {
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.95) 0%, rgba(10, 15, 29, 0.95) 100%);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px 20px;
  margin-bottom: 24px;
  text-align: center;
  position: relative;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}
.ad-tag-badge {
  position: absolute;
  top: 10px;
  left: 14px;
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: 6px;
}
.sponsor-title {
  font-size: 26px;
  font-weight: 900;
  color: #38bdf8;
  letter-spacing: -0.5px;
  margin-bottom: 6px;
}
.sponsor-sub {
  font-size: 12px;
  color: var(--text-muted);
}

/* Responsive Adsterra Containers (Avoid CPM drop via viewability & mobile fit) */
.adsterra-header-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 50px;
  overflow: hidden;
}
.adsterra-desktop-728 {
  display: none;
}
.adsterra-mobile-320 {
  display: block;
}
@media (min-width: 768px) {
  .adsterra-desktop-728 {
    display: block;
  }
  .adsterra-mobile-320 {
    display: none;
  }
}

/* Schedule Headline & 3-Day Switcher Tabs */
.schedule-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}
.schedule-heading h2 {
  font-size: 18px;
  font-weight: 900;
  color: var(--text-white);
}
.schedule-heading p {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
}
.day-switcher-tabs {
  display: flex;
  background: rgba(15, 23, 42, 0.9);
  border: 1px solid var(--border-subtle);
  border-radius: 24px;
  padding: 4px;
  gap: 4px;
}
.day-tab-btn {
  background: transparent;
  border: none;
  color: var(--text-silver);
  font-family: inherit;
  font-size: 12px;
  font-weight: 800;
  padding: 6px 18px;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s;
}
.day-tab-btn.active {
  background: var(--accent-emerald);
  color: white;
  box-shadow: 0 2px 12px var(--accent-emerald-glow);
}

/* League Section Header */
.league-group-title {
  font-size: 15px;
  font-weight: 900;
  color: var(--text-white);
  margin: 24px 0 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.league-group-title::before {
  content: '';
  display: inline-block;
  width: 4px;
  height: 18px;
  background: var(--accent-cyan);
  border-radius: 2px;
}

/* Match Row Card (Exact Match to Screenshot) */
.match-row-card {
  background: var(--bg-glass-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  margin-bottom: 12px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
  text-decoration: none;
  color: inherit;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
}
.match-row-card:hover {
  border-color: rgba(16, 185, 129, 0.4);
  background: rgba(18, 27, 49, 0.95);
  transform: translateY(-2px);
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.6);
}
.team-cell {
  display: flex;
  align-items: center;
  gap: 12px;
}
.team-cell.home {
  justify-content: flex-start;
  flex-direction: row-reverse;
  text-align: right;
}
.team-cell.away {
  justify-content: flex-start;
  text-align: left;
}
.team-name {
  font-size: 14px;
  font-weight: 800;
  color: var(--text-white);
}
.team-logo-box {
  width: 40px;
  height: 40px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  flex-shrink: 0;
}
.team-logo-box img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}
.center-intel-cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  text-align: center;
  min-width: 170px;
}
.kickoff-time {
  font-family: var(--font-mono);
  font-size: 24px;
  font-weight: 900;
  color: var(--text-white);
  letter-spacing: -0.5px;
}
.countdown-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: rgba(16, 185, 129, 0.15);
  color: var(--accent-emerald-bright);
  font-size: 11px;
  font-weight: 800;
  padding: 2px 10px;
  border-radius: 12px;
  font-family: var(--font-mono);
}
.meta-channel-row {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 6px;
}
.meta-note {
  font-size: 10px;
  color: #64748b;
}

/* Ad Slots (Header, In-Feed, Sticky) */
.ay-match-compact {
  transition: all 0.2s ease;
}
.ad-card-behind-match {
  background: rgba(16, 185, 129, 0.04);
  border: 1px dashed rgba(16, 185, 129, 0.3);
  border-radius: var(--radius-sm);
  margin-top: -6px;
  margin-bottom: 16px;
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-silver);
}
.ad-slot-container {
  margin: 16px 0;
  text-align: center;
  position: relative;
}
.ad-slot-infeed {
  background: rgba(15, 23, 42, 0.6);
  border: 1px dashed rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-md);
  padding: 16px;
  margin: 20px 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.sticky-ad-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(10, 15, 29, 0.96);
  backdrop-filter: blur(16px);
  border-top: 1px solid var(--border-accent);
  padding: 10px 16px;
  z-index: 999;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 -8px 30px rgba(0, 0, 0, 0.8);
}
.close-sticky-btn {
  position: absolute;
  top: 6px;
  left: 16px;
  background: rgba(239, 68, 68, 0.2);
  border: 1px solid rgba(239, 68, 68, 0.4);
  color: #fca5a5;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Article Post Body for SEO pages */
.article-post-body {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-top: 20px;
}
.cta-watch-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #10b981 0%, #06b6d4 100%);
  color: white;
  text-decoration: none;
  font-weight: 900;
  padding: 10px 24px;
  border-radius: 24px;
  margin-bottom: 20px;
  box-shadow: 0 4px 16px var(--accent-emerald-glow);
}

@media (max-width: 640px) {
  .match-row-card {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 10px;
  }
  .team-cell.home {
    justify-content: center;
    flex-direction: row;
  }
  .team-cell.away {
    justify-content: center;
  }
  .schedule-toolbar {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* Desktop Skyscraper Sidebars (160x600) */
.desktop-side-banner {
  position: fixed;
  top: 80px;
  width: 160px;
  height: 600px;
  z-index: 100;
  display: none;
}
.desktop-side-banner.left {
  left: 12px;
}
.desktop-side-banner.right {
  right: 12px;
}
@media (min-width: 1320px) {
  .desktop-side-banner {
    display: block;
  }
}

/* Status Filter Chips */
.filter-status-chips {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  overflow-x: auto;
  padding-bottom: 4px;
}
.status-chip-btn {
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid var(--border-subtle);
  color: var(--text-silver);
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 18px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s;
}
.status-chip-btn:hover {
  border-color: var(--accent-emerald);
  color: var(--text-white);
}
.status-chip-btn.active {
  background: var(--accent-emerald);
  color: white;
  border-color: var(--accent-emerald);
  box-shadow: 0 2px 10px var(--accent-emerald-glow);
}

/* League Navigation Carousel */
.league-nav-carousel {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  overflow-x: auto;
  padding-bottom: 6px;
  scrollbar-width: thin;
}
.league-pill-btn {
  background: rgba(30, 41, 59, 0.7);
  border: 1px solid var(--border-subtle);
  color: var(--text-silver);
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: 14px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s;
}
.league-pill-btn:hover {
  border-color: var(--accent-cyan);
  color: var(--text-white);
}
.league-pill-btn.active {
  background: rgba(6, 182, 212, 0.2);
  color: var(--accent-cyan);
  border-color: var(--accent-cyan);
}

/* Semantic SEO Evergreen Article Block */
.seo-content-block {
  background: var(--bg-glass-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin: 32px 0 20px;
  line-height: 1.8;
}
.seo-block-title {
  font-size: 18px;
  font-weight: 900;
  color: var(--text-white);
  margin-bottom: 14px;
  border-bottom: 2px solid var(--accent-emerald);
  padding-bottom: 8px;
}
.seo-text-body p {
  font-size: 13px;
  color: var(--text-silver);
  margin-bottom: 12px;
}
.seo-text-body strong {
  color: var(--accent-cyan);
}

/* FAQ Accordion Section */
.faq-accordion-section {
  background: var(--bg-glass-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 30px;
}
.faq-section-title {
  font-size: 17px;
  font-weight: 900;
  color: var(--text-white);
  margin-bottom: 16px;
}
.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding: 10px 0;
}
.faq-item details summary {
  font-size: 14px;
  font-weight: 800;
  color: var(--text-white);
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.faq-item details summary::after {
  content: '▾';
  font-size: 14px;
  color: var(--accent-emerald-bright);
}
.faq-item details[open] summary::after {
  content: '▴';
}
.faq-item details p {
  margin-top: 8px;
  font-size: 13px;
  color: var(--text-silver);
  line-height: 1.7;
}

/* In-Page Stream Modal */
.kora-modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
}
.kora-modal-backdrop {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
}
.kora-modal-content {
  position: relative;
  background: #0f172a;
  border: 1px solid var(--border-accent);
  border-radius: var(--radius-lg);
  width: 92%;
  max-width: 820px;
  overflow: hidden;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.9);
  z-index: 10001;
}
.kora-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  background: rgba(255, 255, 255, 0.03);
  border-bottom: 1px solid var(--border-subtle);
}
.kora-modal-header h3 {
  font-size: 16px;
  font-weight: 900;
  color: var(--text-white);
  margin: 0;
}
.kora-modal-close {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  padding: 4px 8px;
}
.kora-modal-close:hover {
  color: #ef4444;
}
.kora-modal-player {
  background: #000;
  position: relative;
  padding-top: 56.25%;
}
.player-placeholder {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-silver);
  font-size: 14px;
}
.kora-modal-servers {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 20px;
  background: rgba(15, 23, 42, 0.9);
  overflow-x: auto;
}
.server-btn {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-subtle);
  color: var(--text-silver);
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 8px;
  cursor: pointer;
  white-space: nowrap;
}
.server-btn.active {
  background: var(--accent-emerald);
  color: white;
  border-color: var(--accent-emerald);
}

